-- Each case is one transaction and always rolls back.

-- @case 1: only open histories: ended ones excluded, missing department or person dropped, two open histories give two rows; 1753-01-01 and 9999-12-31 start dates; Title '' kept, not NULL
BEGIN;
DELETE FROM humanresources.department;
DELETE FROM humanresources.employee;
DELETE FROM humanresources.employee_department_history;
DELETE FROM person.person;
INSERT INTO humanresources.department ("DepartmentID", "Name", "GroupName") VALUES
  ('1', 'Engineering', 'Research and Development'),
  ('2', 'Sales', 'Sales and Marketing'),
  ('3', 'Unused', 'Executive General and Administration');
INSERT INTO humanresources.employee ("BusinessEntityID", "JobTitle") VALUES
  ('1', 'Engineer'),
  ('2', 'Tester '),
  ('3', 'Clerk'),
  ('4', 'Ghost');
INSERT INTO humanresources.employee_department_history ("BusinessEntityID", "DepartmentID", "StartDate", "EndDate") VALUES
  ('1', '2', '2001-01-01', '2005-06-30'),
  ('1', '1', '2005-07-01', NULL),
  ('1', '9', '2011-01-01', NULL),
  ('2', '1', '1753-01-01', NULL),
  ('2', '2', '9999-12-31', NULL),
  ('3', '2', '2010-01-01', '2010-01-01'),
  ('4', '1', '2002-02-02', NULL);
INSERT INTO person.person ("BusinessEntityID", "Title", "FirstName", "MiddleName", "LastName", "Suffix") VALUES
  ('1', NULL, 'Ann', NULL, 'Lee', NULL),
  ('2', '', 'Bo', 'J', 'Ng', 'Jr.'),
  ('3', 'Mr.', 'Cy', NULL, 'Oh', NULL);
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT * FROM humanresources.v_employee_department;
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['BusinessEntityID', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'JobTitle', 'Department', 'GroupName', 'StartDate']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 only open histories: ended ones excluded, missing department or person dropped, two open histories gi…', got, ARRAY['BusinessEntityID', 'Title', 'FirstName', 'MiddleName', 'LastName', 'Suffix', 'JobTitle', 'Department', 'GroupName', 'StartDate']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', NULL, 'Ann', NULL, 'Lee', NULL, 'Engineer', 'Engineering', 'Research and Development', '2005-07-01'),
  ('2', '', 'Bo', 'J', 'Ng', 'Jr.', 'Tester ', 'Engineering', 'Research and Development', '1753-01-01'),
  ('2', '', 'Bo', 'J', 'Ng', 'Jr.', 'Tester ', 'Sales', 'Sales and Marketing', '9999-12-31');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 only open histories: ended ones excluded, missing department or person dropped, two open histories gi…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;
